20.     public sealed class ArmClientOptions : ClientOptions
21. #pragma warning restore AZC0008 // ClientOptions should have a nested enum called ServiceVersion
22.     {
23.         internal IDictionary<ResourceType, string> ResourceApiVersionOverrides { get; } = new Dictionary<ResourceType, string>();
24. 
25.         /// <summary>
26.         /// Gets or sets Azure cloud environment.
