30.         /// <summary>
31.         /// Sets the api version to use for a given resource type.
32.         /// To find which API Versions are available in your environment you can use the <see cref="ResourceProviderResource.Get"/> method
33.         /// for the provider namespace you are interested in.
34.         /// </summary>
35.         /// <param name="resourceType"> The resource type to set the version for. To determine the appropriate value, you can refer to the corresponding documentation or XML documentation comments of the API. Then, get its resource type from the Resource's ResourceType field.</param>
36.         /// <param name="apiVersion"> The api version to use. </param>
37.         public void SetApiVersion(ResourceType resourceType, string apiVersion)
38.         {
39.             Argument.AssertNotNullOrEmpty(apiVersion, nameof(apiVersion));
40. 
41.             ResourceApiVersionOverrides[resourceType] = apiVersion;
42.         }
43. 
44.         /// <summary>
45.         /// Sets the api versions from an Azure Stack profile.
46.         /// </summary>
47.         public void SetApiVersionsFromProfile(AzureStackProfile profile)
48.         {
49.             var assembly = Assembly.GetExecutingAssembly();
50.             using (Stream stream = assembly.GetManifestResourceStream(profile.GetManifestName()))
51.             {
52.                 var span = BinaryData.FromStream(stream).ToMemory().Span;
53.                 var allProfile = JsonSerializer.Deserialize(span, ArmEnvironmentJsonContext.Default.DictionaryStringDictionaryStringJsonElement);
54.                 var armProfile = allProfile["resource-manager"];
55.                 foreach (var keyValuePair in armProfile)
56.                 {
57.                     var namespaceName = keyValuePair.Key;
58.                     var element = keyValuePair.Value;
59. 
60.                     foreach (var apiVersionProperty in element.EnumerateObject())
61.                     {
62.                         var apiVersion = apiVersionProperty.Name;
63.                         foreach (var resourceTypeItem in apiVersionProperty.Value.EnumerateArray())
64.                         {
65.                             string resourceTypeName = default;
66.                             foreach (var property in resourceTypeItem.EnumerateObject())
67.                             {
68.                                 if (property.NameEquals("resourceType"))
69.                                 {
70.                                     resourceTypeName = property.Value.GetString();
71.                                     break;
72.                                 }
73.                             }
74.                             var resourceType = $"{namespaceName}/{resourceTypeName}";
75.                             ResourceApiVersionOverrides[resourceType] = apiVersion;
